<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { crearProgramacion, listarProgramaciones, prepararProgramacion } from '../services/programacionesHorario'
import type { HorarioTrabajo, RegimenHorario } from '../interfaces/horario.interface'
import type { ProgramacionHorario, TrabajadorProgramacion } from '../interfaces/programacionHorario.interface'
const rows=ref<ProgramacionHorario[]>([]),regimenes=ref<RegimenHorario[]>([]),regimenFiltro=ref<number|null>(null),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),error=ref(''),success=ref(''),wizard=ref(false),preparing=ref(false),saving=ref(false),horarios=ref<HorarioTrabajo[]>([]),trabajadores=ref<TrabajadorProgramacion[]>([])
const today=new Date().toISOString().slice(0,10),form=reactive({regimen_id:0,fecha_inicio:today,fecha_fin:today,horario_default_id:null as number|null,horarios_asignados:{} as Record<number,number>,observacion:''})
const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.',date=(v:string)=>new Date(`${v}T00:00:00`).toLocaleDateString('es-PE'),ready=computed(()=>trabajadores.value.length>0&&horarios.value.length>0),days=computed(()=>form.fecha_inicio&&form.fecha_fin?Math.floor((new Date(form.fecha_fin).getTime()-new Date(form.fecha_inicio).getTime())/86400000)+1:0),records=computed(()=>Math.max(0,days.value)*trabajadores.value.length)
async function load(next=1){loading.value=true;error.value='';try{const r=await listarProgramaciones(regimenFiltro.value,next);rows.value=r.data;regimenes.value=r.regimenes;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(v){error.value=message(v)}finally{loading.value=false}}
async function prepare(){if(!form.regimen_id||!form.fecha_inicio||!form.fecha_fin)return void(error.value='Seleccione régimen y rango de fechas.');if(form.fecha_fin<form.fecha_inicio)return void(error.value='La fecha fin no puede ser anterior a la fecha de inicio.');preparing.value=true;error.value='';try{const r=await prepararProgramacion(form.regimen_id,form.fecha_inicio,form.fecha_fin);horarios.value=r.horarios;trabajadores.value=r.trabajadores;form.horarios_asignados={};trabajadores.value.forEach(t=>form.horarios_asignados[t.id]=0)}catch(v){error.value=message(v)}finally{preparing.value=false}}
function applyAll(){if(!form.horario_default_id)return;trabajadores.value.forEach(t=>form.horarios_asignados[t.id]=form.horario_default_id!)}
async function save(){if(!ready.value)return;const missing=trabajadores.value.some(t=>!form.horarios_asignados[t.id]);if(missing)return void(error.value='Asigne un horario a todos los trabajadores.');if(!confirm(`¿Generar ${records.value} registros diarios para ${trabajadores.value.length} trabajadores?`))return;saving.value=true;try{await crearProgramacion({...form});success.value=`Programación generada correctamente: ${records.value} registros diarios.`;wizard.value=false;await load(1)}catch(v){error.value=message(v)}finally{saving.value=false}}
function open(){wizard.value=true;horarios.value=[];trabajadores.value=[];form.regimen_id=0;form.fecha_inicio=today;form.fecha_fin=today;form.horario_default_id=null;form.observacion='';error.value=''}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/administracion/recursos">Recursos Humanos</RouterLink> / Programación de horarios</nav><header class="hero"><div class="mark">PH</div><div><small>MIA · RR. HH. · CONTROL DE TIEMPOS</small><h1>Programación de horarios</h1><p>Genera jornadas diarias por régimen, trabajador y rango de fechas.</p></div><button @click="open">Nueva programación</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error&&!wizard" class="flash error">{{error}}</p><form class="filters" @submit.prevent="load(1)"><select v-model="regimenFiltro"><option :value="null">Todos los regímenes</option><option v-for="r in regimenes" :key="r.id" :value="r.id">[{{r.codigo}}] {{r.descripcion}}</option></select><button>Filtrar</button><button v-if="regimenFiltro" type="button" class="soft" @click="regimenFiltro=null;load(1)">Limpiar</button></form><section class="card"><div v-if="loading" class="empty">Consultando programaciones…</div><div v-else-if="!rows.length" class="empty">No se encontraron programaciones de horarios.</div><div v-else class="scroll"><table><thead><tr><th>ID</th><th>Régimen</th><th>Fecha inicio</th><th>Fecha fin</th><th>Trabajadores</th><th>Registros diarios</th><th>Estado</th><th>Acción</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td>#{{item.id}}</td><td><b>{{item.regimen?.codigo||'—'}}</b> {{item.regimen?.descripcion}}</td><td>{{date(item.fecha_inicio)}}</td><td>{{date(item.fecha_fin)}}</td><td class="num">{{item.total_trabajadores}}</td><td class="num">{{item.total_registros}}</td><td><span :class="item.estado?'active':'inactive'">{{item.estado?'ACTIVO':'INACTIVO'}}</span></td><td><RouterLink class="detail-link" :to="`/modulos/administracion/recursos/detalle-programacion-horarios?id=${item.id}`">Ver detalle</RouterLink></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}} · {{total}} programaciones</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="wizard" class="overlay" @click.self="wizard=false"><section class="wizard"><header><div><small>GENERACIÓN MASIVA</small><h2>Nueva programación</h2></div><button @click="wizard=false">×</button></header><p v-if="error" class="flash error">{{error}}</p><form class="range" @submit.prevent="prepare"><label>Régimen *<select v-model="form.regimen_id"><option :value="0">Seleccione</option><option v-for="r in regimenes" :key="r.id" :value="r.id">{{r.codigo}} - {{r.descripcion}}</option></select></label><label>Fecha inicio *<input v-model="form.fecha_inicio" type="date"></label><label>Fecha fin *<input v-model="form.fecha_fin" type="date"></label><button :disabled="preparing">{{preparing?'Cargando…':'Cargar'}}</button></form><template v-if="ready"><div class="summary"><b>{{trabajadores.length}} trabajadores</b><span>{{days}} días · {{records}} registros a generar</span><label>Aplicar horario a todos<select v-model="form.horario_default_id" @change="applyAll"><option :value="null">Seleccione</option><option v-for="h in horarios" :key="h.id" :value="h.id">{{h.codigo}} - {{h.descripcion}}</option></select></label></div><div class="worker-scroll"><table><thead><tr><th>#</th><th>Código</th><th>Trabajador</th><th>Horario asignado</th></tr></thead><tbody><tr v-for="(t,i) in trabajadores" :key="t.id"><td>{{i+1}}</td><td><b>{{t.codigo_trabajador}}</b></td><td>{{t.nombre_completo}}</td><td><select v-model="form.horarios_asignados[t.id]"><option :value="0">Seleccione</option><option v-for="h in horarios" :key="h.id" :value="h.id">{{h.codigo}} - {{h.descripcion}}</option></select></td></tr></tbody></table></div><label class="observation">Observación<textarea v-model="form.observacion" rows="2" placeholder="Opcional"></textarea></label><footer><button class="soft" @click="wizard=false">Cancelar</button><button :disabled="saving" @click="save">{{saving?'Generando…':'Generar programación diaria'}}</button></footer></template><p v-else-if="horarios.length===0&&trabajadores.length===0&&!preparing" class="hint">Seleccione el régimen y el rango para cargar horarios y trabajadores disponibles.</p></section></div></div></template>
<style scoped>
.page{--a:#2697ad;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--a);text-decoration:none}.hero{padding:20px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero>div:nth-child(2){flex:1}.hero small{color:var(--a);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.2rem}.hero p{margin:0;color:#7e8a90;font-size:.58rem}button,.detail-link{padding:9px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.5rem;text-decoration:none;cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}.flash{padding:10px}.success{color:#237453;background:#e7f7ef}.error{color:#a64046;background:#fff0f0}.filters{margin-top:12px;padding:12px;display:flex;gap:7px;background:#fff}.filters select{min-width:360px}input,select,textarea{padding:9px;border:1px solid #d7dfe2;border-radius:6px;background:#fff;font:inherit;font-size:.5rem}.soft{color:#64727a;background:#edf1f3}.card{margin-top:12px;background:#fff}.empty,.hint{padding:45px;text-align:center}.scroll,.worker-scroll{overflow:auto}table{width:100%;min-width:800px;border-collapse:collapse;font-size:.49rem}th,td{padding:9px;border:1px solid #e1e7ea;text-align:left}thead{color:#fff;background:#354a55}.num{text-align:center}.active,.inactive{padding:4px 7px;border-radius:9px}.active{color:#247655;background:#e5f5ed}.inactive{color:#a13d45;background:#fdebed}.card>footer,.wizard>footer{padding:10px;display:flex;justify-content:center;align-items:center;gap:9px;font-size:.5rem}.overlay{position:fixed;inset:0;z-index:50;padding:18px;display:grid;place-items:center;background:#0008}.wizard{width:min(1000px,97vw);max-height:94vh;overflow:auto;border-radius:11px;background:#fff}.wizard>header{padding:15px;display:flex;align-items:center;justify-content:space-between}.wizard h2{margin:2p